using AcxiomCRM.Data;using AcxiomCRM.Models;using AcxiomCRM.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
[Authorize]public class FollowUpsController:BaseController
{private readonly ApplicationDbContext _db;private readonly IAuditService _audit;public FollowUpsController(ApplicationDbContext db,UserManager<ApplicationUser> users,IAuditService audit):base(users){_db=db;_audit=audit;}
public async Task<IActionResult>Index(string? status){var q=_db.FollowUps.AsQueryable();if(IsSales)q=q.Where(x=>x.AssignedTo==CurrentUserId);if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);return View(await q.OrderBy(x=>x.FollowUpDate).ToListAsync());}
public IActionResult Create()=>View(new FollowUp{FollowUpDate=DateTime.Today});
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(FollowUp model){if(model.FollowUpDate.Date<DateTime.Today)ModelState.AddModelError(nameof(model.FollowUpDate),"Follow-up date cannot be earlier than today.");if(model.CustomerId==null&&model.LeadId==null)ModelState.AddModelError("","Select a customer or lead.");if(!ModelState.IsValid)return View(model);model.AssignedTo=CurrentUserId;_db.FollowUps.Add(model);await _db.SaveChangesAsync();await _audit.LogAsync("Create","FollowUp",model.FollowUpId.ToString(),newValue:model);return RedirectToAction(nameof(Index));}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Complete(int id){var x=await _db.FollowUps.FindAsync(id);if(x==null||(IsSales&&x.AssignedTo!=CurrentUserId))return NotFound();x.Status="Completed";await _db.SaveChangesAsync();await _audit.LogAsync("Complete","FollowUp",id.ToString(),newValue:x);return RedirectToAction(nameof(Index));}
}
